def apply_twice(f, x):
    """Call f on x, then call f again on that result."""
    return f(f(x))


def add_three(n: int) -> int:
    """Return n plus 3."""
    return n + 3


print(apply_twice(add_three, 10))
print(apply_twice(lambda x: x * 2, 5))
print(apply_twice(lambda s: s + "!", "go"))
